<?php
require dirname(__DIR__).'/bootstrap.php';require __DIR__.'/admin-layout.php';admin_required();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{$name=trim($_POST['name']??'');$slug=trim($_POST['slug']??'')?:strtolower(trim(preg_replace('/[^A-Za-z0-9-]+/','-', $name),'-'));if(!$name)throw new RuntimeException('Category name is required.');$img=upload_image($_FILES['image']??[],'categories');$q=$pdo->prepare('INSERT INTO categories(name,slug,description,image,active) VALUES(?,?,?,?,1)');$q->execute([$name,$slug,trim($_POST['description']??''),$img]);flash('Category added.');redirect('categories.php');}catch(Throwable $e){$error=$e->getMessage();}}$rows=$pdo->query('SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();admin_header('Categories');if($error)echo '<div class="notice error">'.e($error).'</div>'; ?><form method="post" enctype="multipart/form-data" class="admin-form admin-panel"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Name<input name="name" required></label><label>Slug<input name="slug"></label><label>Description<input name="description"></label><label>Image<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><button class="button">ADD CATEGORY</button></form><div class="admin-panel table-wrap"><table><tr><th>Name</th><th>Products</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=$r['product_count']?></td></tr><?php endforeach;?></table></div><?php admin_footer(); ?>
